theorem extracted_formal_statement_0 {n : ℕ+} {t μ : ℝ} {h : EuclideanSpace ℝ (Fin ↑n) → ℝ}
  (lasso : h = fun y => μ • ∑ i, ‖y i‖) (x xm : EuclideanSpace ℝ (Fin ↑n)) (tpos : 0 < t) (μpos : 0 < μ)
  (minpoint : ∀ (i : Fin ↑n), xm i = sign (x i) * ((|x i| - t * μ) ⊔ 0)) :
  let g := (t * μ) • fun x => ∑ i, ‖x i‖;
  g = t • h → prox_prop g x xm → (1 / (t * μ)) • (x - xm) ∈ SubderivAt (fun x => ∑ i, ‖x i‖) xm := sorry

theorem extracted_formal_statement_4 {n m : ℕ+} {b : Fin ↑m → ℝ} {A : Matrix (Fin ↑m) (Fin ↑n) ℝ}
  (h_original_goal : ConvexOn ℝ Set.univ fun x => 1 / 2 * ‖A *ᵥ x - b‖ ^ 2) (x : EuclideanSpace ℝ (Fin ↑n)) :
  x ∈ Set.univ → ∀ y ∈ Set.univ, inner (Aᵀ *ᵥ (A *ᵥ x - b) - Aᵀ *ᵥ (A *ᵥ y - b)) (x - y) ≥ 0 := sorry

theorem extracted_formal_statement_5 {n m : ℕ+} {b : Fin ↑m → ℝ} {A : Matrix (Fin ↑m) (Fin ↑n) ℝ}
  (x : EuclideanSpace ℝ (Fin ↑n)) :
  let f := fun x => 1 / 2 * A *ᵥ x ⬝ᵥ A *ᵥ x;
  let f' := fun x => Aᵀ *ᵥ A *ᵥ x;
  HasGradientAt f (f' x) x →
    let h := fun x => b ⬝ᵥ A *ᵥ x;
    let h' := fun x => Aᵀ *ᵥ b;
    HasGradientAt h (h' x) x →
      let φ := fun x => 1 / 2 * ‖A *ᵥ x - b‖ ^ 2;
      let φ' := fun x => Aᵀ *ᵥ (A *ᵥ x - b);
      HasGradientAt (fun x => 1 / 2 * ‖A *ᵥ x - b‖ ^ 2) (Aᵀ *ᵥ (A *ᵥ x - b)) x → HasGradientAt φ (φ' x) x := sorry
